}

class Solution {
public:
  bool isUnique(string astr) {
    bool seen[128] = {};
    for (char c : astr) {
      if (seen[(unsigned char)c]) return false;
      seen[(unsigned char)c] = true;
    }
    return true;
  }
};

func isUnique(astr string) bool {
	seen := make([]bool, 128)
	for i := 0; i < len(astr); i++ {
		c := astr[i]
		if seen[c] {
			return false
		}
		seen[c] = true
	}
	return true
}

class Solution {
  public boolean isUnique(String astr) {
    boolean[] seen = new boolean[128];
    for (int i = 0; i < astr.length(); i++) {
      char c = astr.charAt(i);
      if (seen[c]) return false;
      seen[c] = true;
    }
    return true;
  }
}

class Solution:
    def isUnique(self, astr: str) -> bool:
        seen = set()
        for c in astr:
            if c in seen:
                return False
            seen.add(c)
        return True

impl Solution {
  pub fn is_unique(astr: String) -> bool {
    let mut seen = [false; 128];
    for c in astr.bytes() {
      if seen[c as usize] {
        return false;
      }
      seen[c as usize] = true;
    }
    true
  }
}

const isUnique = (astr: string): boolean => {
  const seen = new Set<string>();
  for (const c of astr) {
    if (seen.has(c)) return false;
    seen.add(c);
  }
  return true;
};
